import type { ColabOneLocale } from "./flags";

export type ColabOneLocaleTable = Record<ColabOneLocale, string>;

function row(
  zhCN: string,
  enUS: string,
  zhTW: string,
  zhHK: string,
  jaJP: string,
  koKR: string,
): ColabOneLocaleTable {
  return {
    "zh-CN": zhCN,
    "en-US": enUS,
    "zh-TW": zhTW,
    "zh-HK": zhHK,
    "ja-JP": jaJP,
    "ko-KR": koKR,
  };
}

