    "Enter the full script to narrate. Long scripts are split by punctuation, normalized to -23 LUFS, and stitched seamlessly.",
    "輸入主播需要朗讀的完整文稿，長文稿將依標點分句合成、統一 -23 LUFS 響度並無縫拼接。",
