    "音声がこの長さを超えると無音区間または文末で自動分割し、末尾フレームを引き継いで長尺動画の色ずれを防ぎます。",
    "전체 오디오가 이 길이를 초과하면 무음 구간 또는 문장 경계에서 자동 분할하고 마지막 프레임을 이어 렌더링해 장편 영상의 색번짐을 방지합니다.",
